const fs = require('fs');
const path = require('path');
const vmm = require('vm');
const SRC = JSON.parse(fs.readFileSync(path.join(__dirname, 'src_g4_science_u2.json'), 'utf8'));
const OUT = path.join(__dirname, '..', 'data', 'g4_science_u2.js');
const DIR = '2단원_물의상태변화';
