const UNIT = 2, UT = '물의 상태 변화', PREV_KEY = 'g4_science:u1_l11';

const TN = (a1, a2, watch, min) => ({ ask: [a1, a2], watch, min });
const nm = (s) => String(s || '').replace(/\*\*/g, '');
const EMO = /[\u{1F000}-\u{1FFFF}\u2600-\u27BF\u2B00-\u2BFF\uFE0F\u200D\u20E3]/gu;
const plain = (s) => nm(s).replace(EMO, '').replace(/\s+/g, ' ').trim();
const S = (k, i) => SRC[k].slides[i];
/* 원문 카드(fx-card) → tools 카드 */
const cardsFig = (sl, chain) => ({ k: chain ? 'chain' : 'tools', items: sl.cards.map(c => { const ls = nm(c.label).split('\n'); return { emoji: c.emoji, name: ls[0], kind: ls.slice(1).join(' ') || undefined }; }) });
/* 시뮬 ① 예상→관찰 → tools/chain: [이름, 원문 관찰 결과(ans)의 한 토막] */
const poseFig = (sl, rows, chain) => ({ k: chain ? 'chain' : 'tools', items: rows.map((r, i) => { const it = sl.data.items[i]; return { emoji: it.emoji, name: r[0], kind: r[1] }; }) });
/* 차시 고유 시뮬 → tools/chain: [그림, 이름, 아래 줄] — 이름·아래 줄은 원문 시뮬 글 토막(게이트가 원문 함수 본문에서 확인) */
const simFig = (rows, chain) => ({ k: chain ? 'chain' : 'tools', items: rows.map(r => ({ emoji: r[0], name: r[1], kind: r[2] })) });
/* 예상 장(recall) → 차례 카드: 이름·아래 줄 = 원문 글 토막 */
const recallFig = (rows) => ({ k: 'chain', items: rows.map(r => ({ emoji: r[0], name: r[1], kind: r[2] })) });
/* 목록 장(list) → tools: 원문 그림 · 이름 = 교사 짧은 이름 · 아래 줄 = 원문 줄 그대로 */
const listFig = (sl, names) => ({ k: 'tools', items: sl.items.map((it, i) => ({ emoji: it.emoji, name: names[i], kind: plain(it.t) })) });
/* 시뮬 ② 살펴보기 → tools: 원문 이름·그림 · 아래 줄 = 원문 결과 줄 line 번째 */
const featFig = (sl, line, chain) => ({ k: chain ? 'chain' : 'tools', items: Object.values(sl.data.data).map(f => ({ emoji: f.emoji, name: f.name, kind: plain(f.feats[Array.isArray(line) ? line.shift() : line]) })) });
/* 시뮬 ② 살펴보기 → ask 두 갈래 */
const featAsk = (sl, q, yesIds, x) => { const d = sl.data.data; return Object.assign({ k: 'ask', q, yes: Object.keys(d).filter(id => yesIds.indexOf(id) >= 0).map(id => ({ name: d[id].name, emoji: d[id].emoji })), no: Object.keys(d).filter(id => yesIds.indexOf(id) < 0).map(id => ({ name: d[id].name, emoji: d[id].emoji })) }, x || {}); };

/* 직전 단원 마지막 차시(4-1 과학 u1_l11 「자석의 이용」 단원 마무리) exit */
const PREV_EXIT = (() => { const L = {}; const c = { window: { LESSONS: L } }; c.window.window = c.window; vmm.createContext(c); vmm.runInContext(fs.readFileSync(path.join(__dirname, '..', 'data', 'g4_science_u1.js'), 'utf8'), c); return L.u1_l11.slides.find(s => s.block === 'exit_ticket').data.items; })();

