const TYPE = { video: ['video', '🎥', ['concept', 'motivate']], q: ['fun_question', '💡', ['concept', 'basic_problem']], tip: ['tip', '🧩', ['concept', 'misconception']], real: ['real_world', '🌍', ['real_world', 'summary']], game: ['game', '🎮', ['leveled_problem', 'offline_activity']], x: ['misconception', '⚠️', ['misconception', 'basic_problem']], e: ['example', '📝', ['concept', 'offline_activity']], c: ['checklist', '✅', ['next_lesson']] };
const PFX = { video: 'v', q: 'q', tip: 't', real: 'r', game: 'g', x: 'x', e: 'e', c: 'c' };
function extras(n, list) {
  const cnt = {};
  return list.map(line => {
    const p = line.split('|'); const k = p[0]; cnt[k] = (cnt[k] || 0) + 1; const [type, icon, fit] = TYPE[k];
    const id = PFX[k] + '_l' + n + '_' + cnt[k];
    if (k === 'video') return { id, type, icon, title: p[1], url: 'https://www.youtube.com/results?search_query=' + encodeURIComponent(p[2]).replace(/%20/g, '+'), description: p[3], source: '유튜브 검색 (교사 사전 확인 권장)', fit_slides: fit };
    return { id, type, icon, title: p[1], content: p[2], fit_slides: fit };
  });
}
/* 원문 장 → 개념 말풍선 글: 정리 카드 장 = 원문 말풍선 그대로 · 예상 장 = 원문 글 그대로 · 시뮬 ①②·목록 장 = 교사 한 줄(lead) — 게이트 F 가 같은 규칙으로 되짚는다 */
function srcContent(sl, lead) { if (sl.kind === 'pose' || sl.kind === 'feat' || sl.kind === 'sim' || sl.kind === 'list') return lead || ''; if (sl.kind === 'recall') return sl.recall || ''; return sl.text || ''; }
/* 원문 문항 → 기본 문제 */
function problemData(q, title, body, icon) {
  const d = { title, scenario: { icon: icon || '🔬', body: [body, q.body].filter(Boolean).join('\n') }, question: q.t };
  if (q.kind === 'mcq') { d.options = q.opts.map((t, i) => (i === q.ci ? { text: t, correct: true } : { text: t })); d.note = '풀이: ' + q.hints[1] + ' → **' + nm(q.opts[q.ci]) + '**'; }
  else if (q.kind === 'ms') { d.options = q.chips.map(c => (c.hit ? { text: c.t, correct: true } : { text: c.t })); d.multi = true; d.note = '풀이: ' + q.hints[1] + ' → 알맞은 것 **' + q.chips.filter(c => c.hit).length + '개**'; }
  else if (q.kind === 'cls') { d.scenario.body += '\n나눌 것: ' + q.items.map(it => it.emoji + ' ' + it.t).join(' · ') + '\n통: ' + q.bins.map(b => b.name).join(' · '); d.answer = q.bins.map(b => b.name + ' — ' + q.items.filter(it => it.bin === b.id).map(it => it.t).join(' · ')).join(' / '); d.note = '풀이: ' + q.hints[1]; }
  else if (q.kind === 'mt') { d.scenario.body += '\n왼쪽: ' + q.pairs.map(p => p[0].replace(/\n/g, ' ')).join(' · ') + '\n오른쪽: ' + q.pairs.map(p => p[1]).join(' · '); d.answer = q.pairs.map(p => p[0].replace(/\n/g, ' ') + ' ↔ ' + p[1]).join(' / '); d.note = '풀이: ' + q.hints[1]; }
  return d;
}

